import{_ as n,o as r,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const u=JSON.parse('{"title":"Reports erstellen und anpassen","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/reportdesigner.md","filePath":"reporting/reportdesigner.md"}'),a={name:"reporting/reportdesigner.md"};function s(l,e,o,d,g,p){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="reports-erstellen-und-anpassen" tabindex="-1">Reports erstellen und anpassen <a class="header-anchor" href="#reports-erstellen-und-anpassen" aria-label="Permalink to &quot;Reports erstellen und anpassen&quot;">​</a></h1><p>Gestalten Sie einen Report auf Grundlage einer vorhandenen Vorlage oder erstellen Sie eine neue Liste. Beginnen Sie mit einer einfachen Ausgabe und kontrollieren Sie Änderungen regelmäßig in der Vorschau.</p><h2 id="den-passenden-einstieg-wahlen" tabindex="-1">Den passenden Einstieg wählen <a class="header-anchor" href="#den-passenden-einstieg-wahlen" aria-label="Permalink to &quot;Den passenden Einstieg wählen&quot;">​</a></h2><ul><li>Den Aufbau verstehen: <a href="/reporting/reportdesigner/was-leistet-ein-report-in-schild-nrw-3.html">Wie ein Report Daten zu einer Ausgabe zusammenführt</a> und <a href="/reporting/reportdesigner/reportdesigner.html">Den Reportdesigner öffnen und verwenden</a>.</li><li>Eine vorhandene Vorlage verändern: <a href="/reporting/reportdesigner/einen-vorhandenen-report-anpassen.html">Einen vorhandenen Report anpassen</a>.</li><li>Eine neue Liste mit Unterstützung erstellen: <a href="/reporting/reportdesigner/einen-neuen-report-mit-dem-berichtsassistenten-erstellen.html">Einen Report mit dem Berichtsassistenten erstellen</a>.</li><li>Den Report von Grund auf aufbauen: <a href="/reporting/reportdesigner/neuen-report-erstellen.html">Einen Report ohne Assistenten erstellen</a>.</li></ul><h2 id="eine-vorlage-bearbeiten" tabindex="-1">Eine Vorlage bearbeiten <a class="header-anchor" href="#eine-vorlage-bearbeiten" aria-label="Permalink to &quot;Eine Vorlage bearbeiten&quot;">​</a></h2><ol><li>Öffnen Sie die Vorlage in der Reportverwaltung über <strong>Report bearbeiten</strong>.</li><li>Passen Sie im <strong>Entwurf</strong> Schrift, Anordnung und Datenfelder an. Die <a href="/reporting/reportdesigner/einen-vorhandenen-report-anpassen.html">Anleitung zur Schulbescheinigung</a> zeigt ein vollständiges Beispiel.</li><li>Kontrollieren Sie die Ausgabe über <strong>Vorschau</strong>.</li><li>Speichern Sie eine eigene Fassung unter einem eigenen Dateinamen. So wird sie beim Aktualisieren der Basisreports nicht durch eine gleichnamige Paketdatei ersetzt.</li></ol><h2 id="begriffe-und-probleme-klaren" tabindex="-1">Begriffe und Probleme klären <a class="header-anchor" href="#begriffe-und-probleme-klaren" aria-label="Permalink to &quot;Begriffe und Probleme klären&quot;">​</a></h2><ul><li>Begriffe und Elemente nachschlagen: <a href="/reporting/reportdesigner/glossar-zum-reportdesigner.html">Begriffe des Reportdesigners</a>.</li><li>Eine Ausgabe mit Bildfehlern reparieren: <a href="/reporting/reportdesigner/problem-bei-der-verwendung-von-grafiken-tutorial.html">Grafikfehler in Reports beheben</a>.</li><li>Schriftarten und Sonderzeichen in einer PDF-Ausgabe erhalten: <a href="/reporting/reportdesigner/probleme-mit-fehlenden-schriftarten-im-pdf-dokument-tutorial.html">Schriftarten und Sonderzeichen in PDF-Ausgaben</a>.</li><li>Weitere Hilfe und Lernangebote finden: <a href="/reporting/reportdesigner/reportdesigner-hilfe-wissen-themenuebersicht.html">Hilfe und Fortbildung zum Reportdesigner</a>.</li></ul><p>Für einen Überblick nach Aufgaben verwenden Sie <a href="/reporting/reportdesigner/reportdesigner-schnelleinstieg.html">Den passenden Einstieg in den Reportdesigner finden</a>. Die <a href="/reporting/reportdesigner/reports-erstellen-anpassen-themenuebersicht.html">Einführung in die Reporterstellung</a> verbindet die Anleitungen mit den Grundlagen des Editors. Weiterführende Regeln stehen unter <a href="/reporting/basisreports/basisreportsammlung-designrichtlinien.html">Reports übersichtlich und wartbar gestalten</a>.</p>',9)])])}const f=n(a,[["render",s]]);export{u as __pageData,f as default};
